// Collect keywords that are new or older than recheckAfterDays, dedupe them and split into batches.
const s = $('Settings').first().json;
const cutoff = Date.now() - Number(s.recheckAfterDays) * 86400000;
const seen = new Set();
const todo = [];
for (const item of $input.all()) {
  const kw = String(item.json.keyword || '').trim(); // keep sheet text as-is so the upsert matches the row
  if (!kw || seen.has(kw.toLowerCase())) continue;
  seen.add(kw.toLowerCase());
  const last = Date.parse(item.json.checked_at || '');
  if (!isNaN(last) && last > cutoff) continue; // fresh enough, skip to save credit
  todo.push(kw);
}
const sources = String(s.sources).split(',').map(x => x.trim()).filter(Boolean);
const size = Math.max(1, Number(s.batchSize));
const out = [];
for (let i = 0; i < todo.length; i += size) {
  out.push({ json: {
    keywords: todo.slice(i, i + size),
    sources,
    location: s.location,
    trademarkCheck: true,
    maxTotalChargeUsd: Number(s.maxSpendPerBatchUsd),
  }});
}
return out; // empty list = nothing to check, workflow stops here

// Turn raw metrics into a verdict you can sort by in the sheet.
const s = $('Settings').first().json;
const out = [];
for (const { json: r } of $input.all()) {
  if (r.type && r.type !== 'keyword') continue; // skipped/invalid rows
  const g = r.googleSearchVolume ?? null;
  const a = r.amazonSearchVolume ?? null;
  const vol = Math.max(g ?? 0, a ?? 0);
  const kd = r.keywordDifficulty ?? null;
  const tm = r.trademarkRisk || 'none';
  let verdict, reason;
  if (tm === 'high' || tm === 'medium') { verdict = 'AVOID'; reason = `Trademark risk ${tm}: ${(r.trademarkFlaggedPhrases || []).join(', ')}`; }
  else if (vol < Number(s.minVolume)) { verdict = 'LOW VOLUME'; reason = `Max monthly volume ${vol} < ${s.minVolume}`; }
  else if (kd !== null && kd > Number(s.maxDifficulty)) { verdict = 'HARD'; reason = `Difficulty ${kd} > ${s.maxDifficulty}`; }
  else { verdict = 'GO'; reason = tm === 'low' ? 'Volume and difficulty OK; low trademark risk, review matches' : 'Volume and difficulty OK'; }
  out.push({ json: {
    keyword: r.inputKeyword || r.keyword,
    verdict, reason,
    google_volume: g, amazon_volume: a,
    cpc_usd: r.cpcUsd ?? null,
    competition: r.competitionLevel ?? null,
    difficulty: kd,
    intent: Array.isArray(r.searchIntent) ? r.searchIntent.join(', ') : (r.searchIntent ?? null),
    trademark_risk: tm,
    trademark_phrases: (r.trademarkFlaggedPhrases || []).join(', '),
    checked_at: new Date().toISOString().slice(0, 10),
  }});
}
return out;
